update wm_material_stock
set quantity_onhand = quantity_onhand - #{quantity},
    update_time = now()
where material_stock_id = #{materialStockId}
  and del_flag = '0'
  and (ifnull(quantity_onhand, 0) - ifnull(quantity_reserved, 0)) >= #{quantity}

mapper.select:
select
from wm_material_stock
del_flag = '0' and material_stock_id = #{id}

select

from wm_material_stock

    del_flag = '0'
    and item_id = #{itemId}
    and frozen_flag = 'N'
    and (ifnull(quantity_onhand, 0) - ifnull(quantity_reserved, 0)) > 0
    and batch_id = #{batchId}
    and warehouse_id = #{warehouseId}
    and location_id = #{locationId}
    and area_id = #{areaId}

order by recpt_date asc, material_stock_id asc

select t.*,
(case when t.min_stock is not null and t.min_stock > 0 and t.quantity_onhand < t.min_stock then 'LOW'
when t.max_stock is not null and t.max_stock > 0 and t.quantity_onhand > t.max_stock then 'HIGH'
else '' end) as warning_type
from (
select
,
(select i.min_stock from md_item i
where i.item_id = wm_material_stock.item_id and i.del_flag = '0' limit 1) as min_stock,
(select i.max_stock from md_item i
where i.item_id = wm_material_stock.item_id and i.del_flag = '0' limit 1) as max_stock
from wm_material_stock

    del_flag = '0'
    and item_id = #{itemId}

        and item_code like concat('%', #{itemCode}, '%')


        and item_name like concat('%', #{itemName}, '%')

    and batch_id = #{batchId}

        and batch_code like concat('%', #{batchCode}, '%')

    and warehouse_id = #{warehouseId}
    and location_id = #{locationId}
    and area_id = #{areaId}
    and frozen_flag = #{frozenFlag}

        and ifnull(quantity_onhand, 0) > 0


) t
order by t.material_stock_id desc

select count(1) from wm_material_stock
where del_flag = '0'
  and warehouse_id = #{warehouseId}

select 
from wm_material_stock

    del_flag = '0'
    and ifnull(quantity_onhand, 0) > 0
    and warehouse_id = #{warehouseId}
    and area_id = #{areaId}
    and item_type_id = #{itemTypeId}

order by material_stock_id
